import collections,datetime,hashlib,json,re,types
from pathlib import Path
S=Path('/home/user/src/work-leaf/bench-results/efficiency-mechanism-isolation-20260906T214448Z')
P=Path('/home/user/src/work-leaf/bench-results/efficiency-mechanism-isolation-20260906T214448Z/phases/author-joint-integration-20260915')
run_id='author-joint-integration-004'
A=P/'runs'/run_id/(run_id+'-three-feature-sequential-bench-artifacts')
expected_cwd='/home/user/.codex/wl-author-integration.VrZvTe/author-joint-integration-004/work-leaf-3feature-sequential-bench.b8EKZW/repo'
core=S/'audit_compaction.py'
errors=[]
def sha(b): return hashlib.sha256(b).hexdigest()
def issue(message): errors.append(message)
originals={}
def read(p):
    p=p.resolve(); data=p.read_bytes()
    value=sha(data)
    if str(p) in originals and originals[str(p)]!=value: issue('source changed during read: '+str(p))
    originals.setdefault(str(p),value)
    return data
archive_files=sorted(p for p in A.rglob('*') if p.is_file())
for p in archive_files: read(p)
for p in [core,P/'logs'/f'{run_id}.exit.json',P/'PHASE-MANIFEST.json',P/'PHASE-RESULT.json',P/'PROTOCOL.md']: read(p)
assert originals[str(core)]=='dd5127f937ec1cc4d41a443ba7640fca93e82484f345ac8c56aeef5325d68153'
mod=types.ModuleType('existing_native_audit'); mod.__file__=str(core)
exec(compile(read(core),str(core),'exec'),mod.__dict__)
cached_core=NativeCache(Path('/home/user/src/work-leaf/bench-results/efficiency-mechanism-isolation-20260906T214448Z/phases/author-joint-integration-20260915/postcapture/author-joint-integration-004/native-core'),originals[str(core)])
original_core=mod.audit_rollout
mod.audit_rollout=lambda rows,metadata,model,effort: cached_core.run(original_core,rows,metadata,model,effort)
def rows(p): return list(mod.json_rows(read(p)))
metadata=rows(A/'observation/rollout-metadata.jsonl')
analysis=json.loads(read(A/'observation/analysis.json'))
report=json.loads(read(A/'report.json'))
exit_receipt=json.loads(read(P/'logs'/f'{run_id}.exit.json'))
observer={x['thread_id']:x for x in analysis['threads']}
meta={x['thread_id']:x for x in metadata}
if len(meta)!=len(metadata): issue('duplicate metadata thread')
public=collections.defaultdict(list)
population=sorted(list((A/'runs').glob('*.jsonl'))+list((A/'runs').glob('*.host/invocation-*/stdout.jsonl')))
for p in population:
    rr=rows(p)
    starts=[(n,r) for n,r in enumerate(rr,1) if r.get('type')=='thread.started']
    ends=[(n,r) for n,r in enumerate(rr,1) if r.get('type')=='turn.completed']
    bad=public_lifecycle(rr)
    if len(starts)!=1:
        issue('public lifecycle has no unique owner: '+str(p))
        continue
    if bad: issue('public lifecycle incomplete: '+str(p))
    tid=starts[0][1]['thread_id']
    host=p.name=='stdout.jsonl'
    prompt=p.parent/'prompt.txt' if host else p.with_suffix('.prompt.txt')
    role=p.parent.parent.name.removesuffix('.host') if host else p.stem
    req=json.loads(read(p.parent/'request.json')) if host else None
    pb=read(prompt)
    if req and req.get('prompt_sha256')!=sha(pb): issue('request prompt hash mismatch: '+str(p))
    public[tid].append({'path':str(p),'prompt_path':str(prompt),'prompt_sha256':sha(pb),'prompt_bytes':len(pb),'role':role,
        'invocation':int(p.parent.name.rsplit('-',1)[1]) if host else None,
        'public_usage':mod.metrics(mod.checked_usage(ends[0][1].get('usage'))) if len(ends)==1 else None,
        'public_completion_line':ends[0][0] if len(ends)==1 else None})
if set(public)!=set(meta) or set(observer)!=set(meta): issue('public/metadata/observer thread census mismatch')
def order(x):
    r=x['role']
    if r=='linearize-plan': return (0,0,0)
    if r=='linearize-accept': return (1,0,0)
    if r.endswith('-implement'): return (0,0,x['invocation'] or 0)
    if '-fix-' in r: return (1,int(r.rsplit('-',1)[1]),x['invocation'] or 0)
    if '-review-' in r: return (0,int(r.rsplit('-',1)[1]),0)
    raise ValueError('unknown stage order '+r)
threads=[]; global_records={}; joined=[]; markers=[]
for tid,m in meta.items():
    rel=Path(m['source_relative_path'])
    native=(Path('/home/user/.codex/sessions')/rel).resolve()
    if rel.is_absolute() or not native.is_relative_to(Path('/home/user/.codex/sessions')): raise ValueError('native escape')
    data=read(native)
    if sha(data)!=m['source_sha256']: issue('metadata native source SHA mismatch: '+tid)
    rr=list(mod.json_rows(data))
    item=mod.audit_rollout(rr,m,'gpt-5.5','xhigh')
    errors.extend(tid+': '+x for x in item['errors'])
    epochs=[]; epoch_by_id={}; current=None
    contexts=[]; event_counts=collections.Counter()
    for n,r in enumerate(rr,1):
        q=r.get('payload',{}); kind=r.get('type')
        if kind=='session_meta':
            for k,v in [('cwd',expected_cwd),('cli_version','0.153.4'),('model_provider','openai')]:
                if q.get(k)!=v: issue(tid+': session '+k+' mismatch')
        if kind=='turn_context':
            contexts.append({'line':n,**{k:q.get(k) for k in ['turn_id','cwd','model','effort']}})
            if q.get('cwd')!=expected_cwd: issue(tid+': context cwd mismatch')
        if kind=='event_msg':
            typ=q.get('type'); event_counts[typ]+=1
            if typ=='task_started':
                if current is not None: issue(tid+': overlapping task')
                turn=q.get('turn_id')
                if turn in epoch_by_id: issue(tid+': repeated task identity')
                current={'turn_id':turn,'start_line':n,'end_line':None,'start_timestamp':r.get('timestamp'),'end_timestamp':None,'prompt_hashes':[]}
                epochs.append(current);epoch_by_id[turn]=current
            elif typ in ['task_complete','turn_aborted']:
                if current is None or q.get('turn_id')!=current['turn_id']: issue(tid+': terminal task mismatch')
                else:
                    current['end_line']=n;current['end_timestamp']=r.get('timestamp');current['terminal']=typ
                    current=None
        if kind=='response_item' and q.get('type')=='message' and q.get('role')=='user' and current is not None:
            texts=[x.get('text','') for x in q.get('content',[]) if x.get('type') in ['input_text','text']]
            current['prompt_hashes'].extend(sha(x.encode()) for x in texts)
            if len(texts)>1: current['prompt_hashes'].append(sha(''.join(texts).encode()))
    pp=sorted(public.get(tid,[]),key=order)
    if len(pp)!=len(epochs): issue(tid+': public/native turn count mismatch')
    byturn=collections.defaultdict(list)
    for rid,record in item['records'].items():
        if rid in global_records: issue('duplicate response across threads '+rid)
        global_records[rid]=record;byturn[record['turn_id']].append(record)
    marker_ids={x['adjacent_native_response_id'] for x in item['compaction_markers'] if x['adjacent_native_response_id']}
    for pub,epoch in zip(pp,epochs):
        turn=epoch['turn_id']; records=byturn.get(turn,[])
        prompt_ok=pub['prompt_sha256'] in epoch['prompt_hashes']
        if not prompt_ok: issue(tid+': exact chronological prompt mismatch '+pub['role'])
        if epoch.get('terminal')!='task_complete': issue(tid+': incomplete task '+turn)
        for rec in records:
            if rec['line']<=epoch['start_line'] or epoch['end_line'] is not None and rec['line']>=epoch['end_line']:
                issue(tid+': response outside task boundary '+rec['response_id'])
        native_usage=mod.metrics(mod.summed(r['usage'] for r in records))
        difference={k:native_usage[k]-(pub['public_usage'] or {}).get(k,0) for k in mod.FIELDS}
        comp_records=[r for r in records if r['response_id'] in marker_ids]
        comp_usage=mod.metrics(mod.summed(r['usage'] for r in comp_records))
        classification='recorded_native_public_unavailable' if pub['public_usage'] is None else 'exact_public_native_match' if not any(difference.values()) else 'native_extra_equals_compaction_associated_usage' if difference=={k:comp_usage[k] for k in mod.FIELDS} else 'unreconciled_difference'
        if classification=='unreconciled_difference': issue(tid+': unexplained usage delta '+turn)
        role=pub['role']
        category='integration' if role.startswith('linearize-') else 'review' if '-review-' in role else 'author_fix' if '-fix-' in role else 'initial_author'
        joined.append({**pub,'thread_id':tid,'turn_id':turn,'category':category,'start_line':epoch['start_line'],'end_line':epoch['end_line'],
            'start_timestamp':epoch['start_timestamp'],'end_timestamp':epoch['end_timestamp'],'terminal':epoch.get('terminal'),
            'exact_prompt_match':prompt_ok,'native_response_ids':[r['response_id'] for r in records],
            'native_usage':native_usage,'native_minus_public':mod.metrics(difference) if pub['public_usage'] is not None else None,'reconciliation':classification,
            'compaction_associated_response_ids':[r['response_id'] for r in comp_records],'compaction_associated_usage':comp_usage})
    if set(byturn)-set(epoch_by_id): issue(tid+': native responses outside all task epochs')
    for marker in item['compaction_markers']: markers.append({'thread_id':tid,'native_path':str(native),**marker})
    threads.append({'thread_id':tid,'native_path':str(native),'native_sha256':sha(data),'metadata_sha_match':sha(data)==m['source_sha256'],
        'public_turn_count':len(pp),'native_started_count':event_counts['task_started'],'native_completed_count':event_counts['task_complete'],'native_aborted_count':event_counts['turn_aborted'],
        'native_response_count':item['response_count'],'duplicate_response_records':item['duplicate_response_records'],
        'core_errors':item['errors'],'native_usage':item['native_usage'],'observer_usage':mod.metrics(mod.checked_usage(observer[tid]['usage'])),
        'native_minus_observer':mod.metrics({k:item['native_usage'][k]-observer[tid]['usage'][k] for k in mod.FIELDS}),
        'contexts':contexts,'incomplete_terminal_turns':[e['turn_id'] for e in epochs if e.get('terminal')!='task_complete']})
public_total=mod.metrics(mod.summed(x['public_usage'] for x in joined if x['public_usage'] is not None))
native_total=mod.metrics(mod.summed(x['usage'] for x in global_records.values()))
categories={}
for c in sorted(set(x['category'] for x in joined)):
    selected=[x for x in joined if x['category']==c]
    categories[c]={'turn_count':len(selected),'native_response_count':sum(len(x['native_response_ids']) for x in selected),
        'public_usage':mod.metrics(mod.summed(x['public_usage'] for x in selected if x['public_usage'] is not None)),
        'native_usage':mod.metrics(mod.summed(x['native_usage'] for x in selected))}
observer_total=mod.metrics(mod.summed(x['usage'] for x in observer.values()))
if {k:public_total[k] for k in mod.FIELDS}!={k:observer_total[k] for k in mod.FIELDS}: issue('public completion aggregate differs from observer aggregate')
after={p:sha(Path(p).read_bytes()) for p in originals}
changed=[p for p in originals if originals[p]!=after[p]]
if changed: issue('original files changed during audit')
if sorted(str(p) for p in A.rglob('*') if p.is_file())!=[str(p) for p in archive_files]: issue('archive file population changed during audit')
result={'schema_version':1,'created_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'run_id':run_id,
    'scope':'one published archive; ordinary runs JSONL plus author host invocation stdout; exact chronological prompt joins to finalized metadata native files',
    'artifact':str(A),'expected_native_cwd':expected_cwd,'core':{'path':str(core),'sha256':originals[str(core)],'symbol':'audit_rollout','execution_count':len(threads)},
    'status':'qualified_observed_ledger' if not errors else 'qualification_errors','errors':errors,
    'observer_capture_complete':analysis.get('capture_complete'),'observer_session_only_threads':analysis.get('session_only_threads'),
    'launcher_exit_code':exit_receipt.get('launcher_exit_code'),'workflow_result':report.get('workflow_result'),
    'public_file_count':len(population),'joined_completed_turn_count':len(joined),'thread_count':len(threads),
    'native_unique_response_count':len(global_records),'compaction_marker_count':len(markers),
    'public_usage':public_total,'observer_usage':observer_total,'native_usage':native_total,
    'native_minus_public':mod.metrics({k:native_total[k]-public_total[k] for k in mod.FIELDS}),
    'category_totals':categories,'threads':threads,'turns':joined,'records':global_records,'compaction_markers':markers,
    'capture_qualification':{'all_public_turns_joined':len(joined)==len(population),'all_joined_prompts_exact':all(x['exact_prompt_match'] for x in joined),
       'recorded_incomplete_turns':[x for t in threads for x in t['incomplete_terminal_turns']],
       'unknown_unfinished_tail_observed':any(t['incomplete_terminal_turns'] for t in threads),
       'whole_provider_hidden_work_absence_proven':False,
       'limit':'Complete observed terminal population, not proof of unrecorded provider work; marker adjacency is association, not proof of provider-internal call type. No frozen primary accounting is overwritten.'},
    'original_hashes_before':originals,'original_hashes_after':after,'original_archive_file_count':len(archive_files),'original_sources_hashed':len(originals),'originals_changed':changed}
print(json.dumps(result,separators=(',',':')))
